const input = $input.all()[0].json;

// Función para parsear query cuando viene como string
function parseQueryString(queryString) {
  const result = {};

  const patterns = [
    { key: 'origin', regex: /origin:\s*([^,]+)/i },
    { key: 'businesstypeid', regex: /businesstypeid:\s*([^,]+)/i },
    { key: 'grupoCaptura', regex: /grupoCaptura:\s*([^,]+?)(?=,\s*modelo:|$)/i },
    { key: 'modelo', regex: /modelo:\s*([^,]+?)(?=,\s*pago:|$)/i },
    { key: 'pago', regex: /pago:\s*([^,]+?)(?=,\s*usado:|$)/i },
    { key: 'usado', regex: /usado:\s*([^,]+?)(?=,\s*interes:|$)/i },
    { key: 'interes', regex: /interes:\s*([^,]+)/i }
  ];

  patterns.forEach(({ key, regex }) => {
    const match = queryString.match(regex);
    if (match) {
      result[key] = match[1].trim();
    }
  });

  return result;
}

// Detectar si query es string u objeto
let parsedQuery = {};
if (typeof input.query === 'string') {
  // Caso 1: query es string "origin: ..., modelo: ..."
  parsedQuery = parseQueryString(input.query);
} else if (typeof input.query === 'object' && input.query !== null) {
  // Caso 2: query es objeto { producto: "X-TRAIL", usado: "...", pago: "..." }
  parsedQuery = {
    modelo: input.query.producto || input.query.modelo,
    pago: input.query.pago,
    usado: input.query.usado,
    interes: input.query.interes
  };
}

// Extraer valores finales con fallbacks
const modelo = parsedQuery.modelo || 
              (input.producto !== 'undefined' ? input.producto : '') || '';

const pago = parsedQuery.pago || 
            (input.pago !== 'undefined' ? input.pago : '') || '';

const usado = parsedQuery.usado || 
             (input.usado !== 'undefined' ? input.usado : '') || '';

const interes = parsedQuery.interes || 
               (modelo && pago && usado ? 'alto' : 'bajo');

// Construir pilot_notes
const pilot_notes = `Modelo: ${modelo || 'No especificado'}
Pago: ${pago || 'No especificado'}
Usado: ${usado || 'No especificado'}
Interés: ${interes}`;

// Output final
const output = {
  name: input.name,
  from: input.from,
  idConversation: input.idConversation,
  origin: parsedQuery.origin || input.origin || '',

  // Normalizar businesstypeid y grupoCaptura (con o sin espacio)
  businesstypeid: parsedQuery.businesstypeid 
                   || input['businesstypeid ']?.trim() 
                   || input.businesstypeid?.trim() 
                   || '',

  grupoCaptura: parsedQuery.grupoCaptura 
                   || input['grupoCaptura ']?.trim() 
                   || input.grupoCaptura?.trim() 
                   || '',

  // 🔥 Agregados obligatorios al output:
  producto: input.producto || parsedQuery.modelo || '',
  usado: input.usado || parsedQuery.usado || '',
  pago: input.pago || parsedQuery.pago || '',
  ProductoInteres: input.ProductoInteres || input.producto || parsedQuery.modelo || '',

  pilot_notes: pilot_notes
};

return { json: output };

